#include <string>
#include <iostream>

using namespace std;

int main() {
    string s;
    cin >> s;
    int pos_r = -1, pos_m = -1;
    for (int i = 0; i < 3; ++i) {
        if (s[i] == 'R') {
            pos_r = i;
        }
        if (s[i] == 'M') {
            pos_m = i;
        }
    }
    if (pos_r < pos_m) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}
